<template><view v-if="items?.length" class="plan-movements"><view v-for="(item,i) in items" :key="i" class="plan-movement"><image class="plan-movement-image" :src="frameUrl(item.slug,1)" mode="aspectFit"/><view class="plan-movement-copy"><text class="plan-movement-title">{{name(item.slug)}}</text><text class="plan-movement-dose">{{item.sets}} {{ct('sets')}} × {{item.reps??item.duration_seconds}} {{ct(item.reps?'reps':'seconds')}} · {{ct('rest')}} {{item.rest_seconds}} {{ct('seconds')}}</text></view></view></view></template>
<script setup lang="ts">import {exercises,exerciseName,frameUrl} from '../lib/exercises';import {ct} from '../lib/coach-i18n';defineProps<{items:any[]}>();function name(slug:string){const e=exercises.find(e=>e.slug===slug);return e?exerciseName(e):slug;}</script>
<style scoped>.plan-movements{margin:14px 0}.plan-movement{display:flex;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid #edf0e7}.plan-movement-image{width:48px;height:48px;background:#355740;border-radius:9px;flex-shrink:0}.plan-movement-copy{min-width:0}.plan-movement-title{display:block;font-size:12px;color:#2d5038;line-height:1.5}.plan-movement-dose{display:block;font-size:10px;line-height:1.7;color:#839177;margin-top:4px;overflow-wrap:anywhere}</style>
